async function findPrivateGroupByIdOrName({
	params,
	checkedArchived = true,
	userId,
}: {
	params:
		| {
				roomId?: string;
		  }
		| {
				roomName?: string;
		  };
	userId: string;
	checkedArchived?: boolean;
}): Promise<{
	rid: string;
	open: boolean;
	ro: boolean;
	t: string;
	name: string;
	broadcast: boolean;
}> {
	const room = await getRoomFromParams(params);
	const user = await Users.findOneById(userId, { projection: { username: 1, roles: 1, abacAttributes: 1 } });
	if (!room || !user || !(await canAccessRoomAsync(room, user))) {
		throw new Meteor.Error('error-room-not-found', 'The required "roomId" or "roomName" param provided does not match any group');
	}
	// discussions have their names saved on `fname` property
	const roomName = room.prid ? room.fname : room.name;
	if (checkedArchived && room.archived) {
		throw new Meteor.Error('error-room-archived', `The private group, ${roomName}, is archived`);
	}
	const sub = await Subscriptions.findOneByRoomIdAndUserId(room._id, userId, { projection: { open: 1 } });
	return {
		rid: room._id,
		open: Boolean(sub?.open),
		ro: Boolean(room.ro),
		t: room.t,
		name: roomName ?? '',
		broadcast: Boolean(room.broadcast),
	};
}
	async function _validateIfAlreadyJoined(room, user, extraData): Promise<boolean> {
		if (!room?._id || !user?._id) {
			return false;
		}
		const [canViewJoined, canViewT] = await Promise.all([
			Authorization.hasPermission(user, 'view-joined-room'),
			Authorization.hasPermission(user, `view-${room.t}-room`),
		]);
		// When there's no ABAC setting, license or values on the room, fallback to previous behavior
		if (!room?.abacAttributes?.length || !(await License.hasModule('abac')) || !(await Settings.get<boolean>('ABAC_Enabled'))) {
			const includeInvitations = extraData?.includeInvitations ?? false;
			if (!(await Subscriptions.countByRoomIdAndUserId(room._id, user._id, includeInvitations))) {
				return false;
			}
			return canViewJoined || canViewT;
		}
		return (canViewJoined || canViewT) && Abac.canAccessObject(room, user, AbacAccessOperation.READ, AbacObjectType.ROOM);
	},

API.v1.get(
	'groups.messages',
	{
		authRequired: true,
		query: groupsMessagesQuery,
		response: { ... },
	},
	async function action() {
		const { roomId, roomName, mentionIds, starredIds, pinned } = this.queryParams;
		const findResult = await findPrivateGroupByIdOrName({
			params: {
				...(roomId && { roomId }),
				...(roomName && { roomName }),
			},
			userId: this.userId,
		});
		const { offset, count } = await getPaginationItems(this.queryParams);
		const { sort, fields, query } = await this.parseJsonQuery();
		const parseIds = (ids: string | undefined, field: string) =>
			typeof ids === 'string' && ids ? { [field]: { $in: ids.split(',').map((id) => id.trim()) } } : {};
		const ourQuery = {
			...query,
			rid: findResult.rid,
			...parseIds(mentionIds, 'mentions._id'),
			...parseIds(starredIds, 'starred._id'),
			...(pinned?.toLowerCase() === 'true' ? { pinned: true } : {}),
			_hidden: { $ne: true },
		};
		const { cursor, totalCount } = Messages.findPaginated(ourQuery, { ... });
		const [messages, total] = await Promise.all([cursor.toArray(), totalCount]);
		return API.v1.success({ ... });
	},
);
	if (room?.t !== 'p') {
		throw new Meteor.Error('error-room-not-found', 'The required "roomId" or "roomName" param provided does not match any group');
	}
	return room;
}
