API.v1.get(
	'channels.list',
	{
		authRequired: true,
		permissionsRequired: {
			GET: { permissions: ['view-c-room', 'view-joined-room'], operation: 'hasAny' },
		},
		query: isChannelsListProps,
		response: {
			200: channelsListResponseSchema,
			400: validateBadRequestErrorResponse,
			401: validateUnauthorizedErrorResponse,
			403: validateForbiddenErrorResponse,
		},
	},
	async function action() {
		const { offset, count } = await getPaginationItems(this.queryParams);
		const { sort, fields, query } = await this.parseJsonQuery();
		const hasPermissionToSeeAllPublicChannels = await hasPermissionAsync(this.user, 'view-c-room');
		const { _id } = this.queryParams;
		const ourQuery: Filter<IRoom> = {
			...query,
			...(_id ? { _id } : {}),
			t: 'c',
		};
		if (!hasPermissionToSeeAllPublicChannels) {
			const roomIds = (
				await Subscriptions.findByUserIdAndType(this.userId, 'c', {
					projection: { rid: 1 },
				}).toArray()
			).map((s) => s.rid);
			ourQuery._id = { $in: roomIds };
		}
		// teams filter - I would love to have a way to apply this filter @ db level :(
		const ids = (await Subscriptions.findByUserId(this.userId, { projection: { rid: 1 } }).toArray()).map(
			(item: Record<string, any>) => item.rid,
		);
		ourQuery.$or = [
			{
				teamId: {
					$exists: false,
				},
			},
			{
				teamId: {
					$exists: true,
				},
				_id: {
					$in: ids,
				},
			},
		];
		const { cursor, totalCount } = Rooms.findPaginated(ourQuery, {
			sort: sort || { name: 1 },
			skip: offset,
			limit: count,
			projection: fields,
		});
		const [channels, total] = await Promise.all([cursor.toArray(), totalCount]);
		return API.v1.success({
			channels: await Promise.all(channels.map((room) => composeRoomWithLastMessage(room, this.userId))),
			count: channels.length,
			offset,
			total,
		});
	},
);
export async function checkPermissionsForInvocation(
	userId: IUser['_id'],
	permissionsPayload: PermissionsPayload,
	requestMethod: RequestMethod,
): Promise<boolean> {
	const permissions = permissionsPayload[requestMethod] || permissionsPayload['*'];
	if (!permissions) {
		// how we reached here in the first place?
		return false;
	}
	if (permissions.permissions.length === 0) {
		// You can pass an empty array of permissions to allow access to the method
		return true;
	}
	if (permissions.operation === 'hasAll') {
		return hasAllPermissionAsync(userId, permissions.permissions);
	}
	if (permissions.operation === 'hasAny') {
		return hasAtLeastOnePermissionAsync(userId, permissions.permissions);
	}
	return false;
}

