export const hideRoomMethod = async (userId: string, rid: string): Promise<number> => {
	check(rid, String);
	if (!userId) {
		throw new Meteor.Error('error-invalid-user', 'Invalid user', {
			method: 'hideRoom',
		});
	}
	const { modifiedCount } = await Subscriptions.hideByRoomIdAndUserId(rid, userId);
